<script lang="ts">
  import type { BootstrapData } from '../bootstrap'; import AppShell from '../components/AppShell.svelte'; import { record, text } from '../lib/data';
  let { data }: { data: BootstrapData } = $props(); const system = $derived(record(data.system));
  type Row = { key: string; value: string; good?: boolean };
  function rows(value: unknown, prefix = ''): Row[] { if (Array.isArray(value)) return value.flatMap((item, index) => rows(item, `${prefix}${prefix ? '.' : ''}${index + 1}`)); if (typeof value === 'object' && value !== null) return Object.entries(value).flatMap(([key, item]) => rows(item, `${prefix}${prefix ? '.' : ''}${key}`)); return [{ key: prefix, value: value === null || value === '' ? '—' : typeof value === 'boolean' ? value ? 'Ja' : 'Nein' : String(value), good: typeof value === 'boolean' ? value : undefined }]; }
  const sections = $derived(Object.entries(system));
</script>
<AppShell title="Systeminformationen" area="admin" csrfToken={text(data.csrfToken)}><nav class="subnav"><a href="/admin">Übersicht</a><a href="/admin/security">Sicherheit</a><a class="active" href="/admin/system">System</a></nav><p class="mt-5 opacity-75">Diagnose für Host, PHP, Datenbank, Cache, Komponenten und schreibbare Runtime-Pfade. Kennwörter und geheime Schlüssel werden nicht ausgegeben.</p><div class="mt-6 grid gap-5">{#each sections as [section, content]}<section class="card preset-filled-surface-100-900 overflow-x-auto p-6"><h2 class="h2 capitalize">{section.replaceAll('_', ' ')}</h2><table class="table mt-4"><tbody>{#each rows(content) as row}<tr><th class="text-left"><code>{row.key}</code></th><td>{#if row.good !== undefined}<span class:status-good={row.good} class:status-bad={!row.good} class="status-pill">{row.value}</span>{:else}{row.value}{/if}</td></tr>{/each}</tbody></table></section>{/each}</div></AppShell>
